'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const esc = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name,cls='')=>`<i data-lucide="${esc(name)}" class="${cls}"></i>`;
const icons = ()=>window.lucide?.createIcons();
function syncBranding(){
  // Upgrade markup retained by an already-running Flask process after a visual update.
  const brand=$('.brand');
  if(!brand)return;
  const script=document.currentScript||$('script[src*="/static/js/app.js"]');
  const logoUrl=new URL('../images/logo-mark.svg?v=blue-3',script.src).href;
  let mark=$('.brand-mark',brand);
  if(!mark||mark.tagName!=='IMG'){
    const image=new Image(44,48);
    image.className='brand-mark';
    image.alt='';
    image.src=logoUrl;
    if(mark)mark.replaceWith(image);else brand.prepend(image);
    mark=image;
  }
  let copy=$('.brand-copy',brand);
  if(!copy){
    copy=brand.querySelector('span:last-child')||document.createElement('span');
    copy.className='brand-copy';
    const name=document.createElement('strong');name.textContent='NEU';
    const subtitle=document.createElement('b');subtitle.textContent='Learning Path';
    copy.replaceChildren(name,subtitle);
    if(!copy.parentElement)brand.append(copy);
  }
  brand.setAttribute('aria-label','NEU Learning Path');
  const menu=$('#menu-toggle');
  if(menu&&!$('.mobile-brand')){
    const link=document.createElement('a');
    link.href=brand.getAttribute('href')||'/';
    link.className='mobile-brand';
    link.setAttribute('aria-label','NEU Learning Path');
    const image=new Image(28,30);image.alt='';image.src=logoUrl;
    link.append(image);menu.after(link);
  }
}
syncBranding();
