async function api(path,options={}){
  const response=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json','X-CSRFToken':$('meta[name="csrf-token"]').content,...options.headers}});
  const payload=await response.json().catch(()=>({error:'Không đọc được phản hồi từ máy chủ.'}));
  if(!response.ok)throw new Error(payload.error||'Không thể xử lý yêu cầu.');
  return payload.data;
}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'circle-alert':'circle-check')+`<span>${esc(message)}</span>`;$('#toasts').append(el);icons();setTimeout(()=>el.remove(),4800);}
function openModal(title,subtitle,content,footer='',wide=false){const modal=$('#modal');modal.style.width=wide?'810px':'580px';$('#modal-content').innerHTML=`<div class="modal-header"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="Đóng">${icon('x')}</button></div><div class="modal-body">${content}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal();icons();}
function closeModal(){$('#modal').close();}
function inlineError(message){let el=$('.form-error',$('#modal'));if(!el){el=document.createElement('div');el.className='form-error';$('.modal-body').append(el);}el.textContent=message;el.classList.add('visible');}
function requireAuth(action){if(state.auth)return true;state.pending=action;authModal();return false;}
