const coursePhotoIds={'DEMO-PY':'python','DEMO-DSA':'algorithms','DEMO-DB':'database','DEMO-ADB':'database-admin','DEMO-OOP':'oop','DEMO-WEB':'web','DEMO-API':'api','DEMO-NET':'network','DEMO-OS':'linux','DEMO-SEC':'security','DEMO-ML':'ml','DEMO-DA':'data','DEMO-UX':'ui','DEMO-QA':'testing','DEMO-CLOUD':'cloud'};
const coursePhotoBase=new URL('../images/courses/',(document.currentScript||$('script[src*="/static/js/app.js"]')).src).href;
function coursePhotoKey(course){
  if(coursePhotoIds[course.id])return coursePhotoIds[course.id];
  if(coursePhotos[course.detail?.theme])return course.detail.theme;
  const name=(course.name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').toLowerCase();
  const rules=[[/quan tri.*du lieu/,'database-admin'],[/co so du lieu|database|sql/,'database'],[/python/,'python'],[/giai thuat|thuat toan|cau truc du lieu/,'algorithms'],[/huong doi tuong|java|c\+\+/,'oop'],[/bao mat|an toan.*thong tin/,'security'],[/mang may tinh|truyen.*du lieu/,'network'],[/he dieu hanh|linux/,'linux'],[/tri tue nhan tao|hoc may/,'ml'],[/phan tich.*du lieu|truc quan/,'data'],[/giao dien|tuong tac nguoi/,'ui'],[/kiem thu|chat luong/,'testing'],[/dam may|devops|phan tan|song song/,'cloud'],[/api|dich vu/,'api'],[/web|website/,'web']];
  return rules.find(([pattern])=>pattern.test(name))?.[1]||'testing';
}
function cover(course,detail=false){
  const key=coursePhotoKey(course),photo=coursePhotos[key],tag=detail?'div':'button';
  const attributes=detail?'':` type="button" data-action="detail" data-id="${esc(course.id)}" aria-label="Xem chi tiết ${esc(course.name)}"`;
  return `<${tag} class="course-cover course-cover-photo ${detail?'detail-cover':''}"${attributes}><img class="course-photo" src="${esc(coursePhotoBase+key+'.webp?v=photos-1')}" alt="${esc(photo.alt)}" width="1100" height="700" loading="${detail?'eager':'lazy'}" decoding="async" style="object-position:${photo.position}"><span class="cover-photo-shade" aria-hidden="true"></span><span class="photo-topic">${esc(photo.label)}</span>${course.score!=null?`<span class="match-badge">${icon('sparkles')}${course.score}% phù hợp</span>`:''}</${tag}>`;
}
function courseCard(course){const status=statusOf(course.id);const val=status==='completed'?100:status==='in_progress'?45:0;const label=status==='not_started'?(course.ready===false?'Cần học môn tiên quyết':'Sẵn sàng bắt đầu'):statusLabels[status];return `<article class="course-card">${cover(course)}<div class="course-content"><div class="course-type">${course.source==='DEMO'?'HỌC PHẦN MINH HỌA':'DANH MỤC NEU'} <span>· ${esc(course.code)}</span></div><button class="course-name" data-action="detail" data-id="${esc(course.id)}">${esc(course.name)}</button><div class="course-info"><span>${icon('book-open')}${course.credits!=null?`${course.credits} tín chỉ`:'Chưa rõ tín chỉ'}</span><span>${icon('clock-3')}${course.source==='DEMO'?'45 tiết dự kiến':'Chưa xác minh'}</span></div><div class="course-status"><span class="status-${status}">${label}</span><span>${val}%</span></div><div class="mini-progress"><span class="${val===100?'complete':''}" style="width:${val}%"></span></div><div class="course-bottom"><div class="skill-mini">${(course.skills||Object.keys(course.detail?.skills||{})).slice(0,2).map(s=>`<span>${esc(s)}</span>`).join('')}${!(course.skills||Object.keys(course.detail?.skills||{})).length?'<span>Chưa có ánh xạ kỹ năng</span>':''}</div><button class="card-arrow" data-action="detail" data-id="${esc(course.id)}" aria-label="Chi tiết ${esc(course.name)}">${icon('arrow-up-right')}</button></div></div></article>`;}
function heroArt(){return `<svg viewBox="0 0 280 180" fill="none" aria-hidden="true"><path d="M38 135L93 104L145 133L236 76" stroke="#accadf" stroke-width="1.5" stroke-dasharray="4 5"/><path d="M59 61L108 89L165 54L222 88" stroke="#accadf" stroke-width="1.5" stroke-dasharray="4 5"/><ellipse cx="145" cy="150" rx="77" ry="12" fill="#d8e8f3"/><path d="M79 103L142 68L208 104L145 141Z" fill="#c7dded"/><path d="M79 103V115L145 152V141Z" fill="#a3c6df"/><path d="M145 141V152L208 115V104Z" fill="#b6d3e7"/><path d="M97 83L142 57L190 83L145 109Z" fill="#83b2d4"/><path d="M97 83V103L145 130V109Z" fill="#679bc1"/><path d="M145 109V130L190 103V83Z" fill="#7baacb"/><path d="M121 52L151 35L178 51L149 68Z" fill="#f3f9fd" stroke="#afcce1"/><path d="M121 52V73L149 90V68Z" fill="#d1e4f2" stroke="#afcce1"/><path d="M149 68V90L178 72V51Z" fill="#e4f1fa" stroke="#afcce1"/><path d="M134 54L147 46L161 54L148 62Z" fill="#7aaacd"/><path d="M148 62V72" stroke="#7aaacd" stroke-width="2"/><path d="M60 31L87 46L60 62L33 46Z" fill="white" stroke="#cee1ef"/><path d="M60 62V70L87 54V46" fill="#bdd6e8"/><path d="M60 62L33 46V54L60 70" fill="#d6e7f3"/><path d="M55 43L50 46L55 49M65 43L70 46L65 49M62 41L58 51" stroke="#84adcb" stroke-width="1.8" stroke-linecap="round"/><rect x="210" y="36" width="37" height="37" rx="11" fill="white" stroke="#cee1ef"/><path d="M220 56L225 61L236 49" stroke="#7aa7c8" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="67" cy="114" r="13" fill="#f9fcfe" stroke="#c0d8e9"/><path d="M62 114L66 118L73 110" stroke="#8bb5d3" stroke-width="2" stroke-linecap="round"/><circle cx="213" cy="137" r="5" fill="#afcee4"/><circle cx="168" cy="22" r="3" fill="#b2cde1"/><path d="M100 20V30M95 25H105M232 110V118M228 114H236" stroke="#a6c8e0" stroke-width="1.5" stroke-linecap="round"/></svg>`;}
function hero(){const r=state.run;return `<section class="hero"><div class="hero-content"><span class="hero-pill">${icon('sparkles')}LỘ TRÌNH ĐƯỢC CÁ NHÂN HÓA</span><h2>Trở thành ${esc(r.career_english)}</h2><p>Một hành trình rõ ràng. Những kiến thức đúng đắn. Một tương lai rộng mở.</p><div class="hero-meta"><span>${icon('graduation-cap')}${esc(r.curriculum_name)}</span><span>${icon('calendar-days')}${esc(r.cohort)}</span><button class="btn btn-link" data-action="create">Thay đổi định hướng ${icon('arrow-right')}</button></div></div><div class="hero-art">${heroArt()}</div></section>`;}
function stats(){const r=state.run;const done=chosen().filter(c=>statusOf(c.id)==='completed').length;return `<div class="stats-row"><div class="stat"><span class="stat-icon primary">${icon('book-open')}</span><div><small>Học phần được gợi ý</small><strong>10<span>/ 15 môn</span></strong></div></div><div class="stat"><span class="stat-icon green">${icon('circle-check')}</span><div><small>Môn đã hoàn thành</small><strong>${done}<span>/ 10 môn</span></strong></div><span class="stat-desc green">${done?'Tiếp tục phát huy':'Bắt đầu hôm nay'}</span></div><div class="stat"><span class="stat-icon blue">${icon('layers')}</span><div><small>Tổng số tín chỉ</small><strong>${r.credits}<span>tín chỉ</span></strong></div></div><div class="stat"><span class="stat-icon orange">${icon('goal')}</span><div><small>Bao phủ kỹ năng</small><strong>${Math.round(r.coverage)}<span>%</span></strong></div><span class="stat-desc">Theo mục tiêu nghề</span></div></div>`;}
function tabs(){return `<div class="tabs-bar"><div class="tabs">${[['timeline','route','Lộ trình học tập'],['recommendations','sparkles','Môn được gợi ý'],['graph','network','Đồ thị tri thức'],['skills','chart-no-axes-combined','Kỹ năng mục tiêu']].map(([key,ic,label])=>`<button class="tab ${state.tab===key?'active':''}" data-action="tab" data-id="${key}">${icon(ic)}${label}${key==='recommendations'?'<span class="tab-count">10</span>':''}</button>`).join('')}</div><div class="view-select">Hiển thị<select id="group-select" aria-label="Cách nhóm lộ trình">${option('level','Theo giai đoạn',state.group)}${option('semester','Theo học kỳ',state.group)}</select></div></div>`;}
