function rail(){const r=state.run,done=chosen().filter(c=>statusOf(c.id)==='completed').length,percent=done*10;return `<aside class="rail"><section class="rail-card"><h3 class="rail-title">Tiến độ của bạn ${icon('chart-no-axes-combined')}</h3><div class="progress-ring"><svg viewBox="0 0 122 122"><circle class="ring-bg" cx="61" cy="61" r="51"/><circle class="ring-value" cx="61" cy="61" r="51" stroke-dasharray="${percent*3.2044} 320.44"/></svg><div class="ring-center">${percent}%<small>hoàn thành lộ trình</small></div></div><div class="progress-legend"><span><b></b>Đã hoàn thành (${done})</span><span><b></b>Còn lại (${10-done})</span></div><div class="rail-note">${icon('sparkles')}<span>${done?'Bạn đang tiến gần hơn đến mục tiêu. Mỗi học phần là một bước tiến!':'Hành trình vạn dặm bắt đầu từ một bước chân. Bắt đầu ngay hôm nay!'}</span></div><button class="btn btn-soft btn-small" data-action="save">${icon('bookmark')}Lưu lộ trình của tôi</button></section><section class="rail-card"><h3 class="rail-title">Đích đến của bạn ${icon('flag')}</h3><div class="target-label">NGHỀ NGHIỆP MỤC TIÊU</div><div class="target-career"><span class="target-icon">${icon('code-xml')}</span><div><strong>${esc(r.career_english)}</strong><small>${esc(r.career_name)}</small></div></div><div class="skill-tags">${r.skills.slice(0,5).map(s=>`<span>${esc(s.name)}</span>`).join('')}</div><div class="rail-divider"></div><div class="coverage-row"><span>Mức bao phủ kỹ năng</span><strong>${r.coverage}%</strong></div><div class="mini-progress"><span style="width:${r.coverage}%"></span></div><button class="btn btn-white btn-small" data-action="compare">${icon('git-compare-arrows')}So sánh định hướng</button></section><section class="rail-card graph-mini"><h3 class="rail-title">Vì sao là những môn này?</h3><p>Khám phá cách các môn học kết nối<br>với kỹ năng và nghề nghiệp của bạn.</p>${miniGraph()}<button class="btn btn-link" data-action="tab" data-id="graph">Khám phá đồ thị tri thức ${icon('arrow-right')}</button></section></aside>`;}
function timeline(){const r=state.run;const stages=state.group==='semester'?[...new Set(chosen().map(x=>x.proposed_semester))].sort((a,b)=>a-b).map(s=>({title:`Học kỳ ${s} dự kiến`,name:'Kế hoạch học tập',desc:'Thứ tự học được đề xuất theo quan hệ tiên quyết, không phải lịch mở lớp chính thức.',courses:chosen().filter(c=>c.proposed_semester===s)})):[{title:'Xây nền tảng vững chắc',name:'Bắt đầu từ nền tảng',desc:'Nắm vững kiến thức cốt lõi để tự tin chinh phục những thử thách phía trước.',courses:chosen().filter(c=>c.level===1)},{title:'Phát triển kỹ năng chuyên môn',name:'Kết nối kiến thức',desc:'Ứng dụng nền tảng vào các bài toán thực tế và phát triển kỹ năng chuyên ngành.',courses:chosen().filter(c=>c.level===2)},{title:'Sẵn sàng cho nghề nghiệp',name:'Bứt phá & ứng dụng',desc:'Hoàn thiện năng lực chuyên sâu, xây dựng sản phẩm và sẵn sàng cho công việc.',courses:chosen().filter(c=>c.level===3)}];return `<div class="roadmap-layout"><div class="roadmap-main"><div class="roadmap-intro"><h3>Hành trình học tập <span>${stages.length} giai đoạn phát triển</span></h3><span>${icon('info')}Kế hoạch học tập dự kiến</span></div>${stages.filter(s=>s.courses.length).map((stage,i)=>{const done=stage.courses.filter(c=>statusOf(c.id)==='completed').length;return `<section class="stage"><div class="stage-aside"><div class="stage-top"><span class="stage-label"><span class="step-square">${i+1}</span>Giai đoạn ${i+1}</span><span class="stage-fraction">${done}/${stage.courses.length} môn</span></div><h3>${stage.name}</h3><p>${stage.desc}</p><div class="stage-details"><span>${icon('signal')}${['Nền tảng','Trung cấp','Chuyên sâu'][Math.min(i,2)]}</span><span>${icon('book-open')}${stage.courses.length} học phần</span><span>${icon('layers')}${stage.courses.reduce((n,c)=>n+c.credits,0)} tín chỉ</span><span>${icon('clock-3')}${stage.courses.length*45} tiết dự kiến</span></div><div class="stage-footer">${icon('award')}Tích lũy kiến thức, mở lối tương lai</div></div><div class="stage-body"><span class="timeline-dot ${i?'future':''}">${i?i+1:icon('check')}</span><div class="stage-body-header"><h3>${stage.title}</h3><p>${i===0?'Bắt đầu với những học phần cốt lõi, xây dựng tư duy và kiến thức nền tảng.':stage.desc}</p></div><div class="course-grid">${stage.courses.sort((a,b)=>r.ordering.indexOf(a.id)-r.ordering.indexOf(b.id)).map(courseCard).join('')}</div></div></section>`}).join('')}</div>${rail()}</div>`;}
function recommendationList(){return `<div class="roadmap-intro"><h3>10 học phần phù hợp với bạn</h3><span>${icon('sparkles')}Đã xét ${state.run.combinations_evaluated.toLocaleString('vi-VN')} tổ hợp</span></div><div class="recommend-list">${chosen().map((c,i)=>`<article class="recommend-item"><span class="rank">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(c.name)}</h3><p>${esc(c.reason)}</p><div class="skill-tags" style="margin-top:8px">${c.skills.slice(0,4).map(s=>`<span>${esc(s)}</span>`).join('')}</div></div><div class="recommend-score">${c.score}%<small>điểm phù hợp</small><div class="mini-progress"><span style="width:${c.score}%"></span></div></div><button class="btn btn-white btn-small" data-action="detail" data-id="${c.id}">Chi tiết ${icon('arrow-up-right')}</button></article>`).join('')}</div><h3 class="subheading">5 học phần còn lại</h3><div class="recommend-list">${state.run.items.filter(c=>!c.selected).map(c=>`<article class="recommend-item"><span class="rank">—</span><div><h3>${esc(c.name)}</h3><p>${esc(c.exclusion_reason)}</p></div><div class="recommend-score">${c.score}%</div><button class="btn btn-white btn-small" data-action="detail" data-id="${c.id}">Xem môn học</button></article>`).join('')}</div><div class="demo-callout">${icon('info')}Điểm phù hợp và độ bao phủ là hai chỉ số khác nhau. Điểm được tính theo 5 thành phần; tổ hợp tối ưu cân bằng bao phủ kỹ năng (65%), độ phù hợp (25%) và tính liên tục (10%).</div>`;}
function skillsView(){return `<div class="skill-chart-grid"><div class="chart-card"><h3 class="subheading" style="margin-top:0">Bản đồ kỹ năng nghề nghiệp</h3><canvas id="skill-chart" aria-label="Biểu đồ mức độ bao phủ kỹ năng"></canvas></div><div class="chart-card"><h3 class="subheading" style="margin-top:0">Kỹ năng được phát triển</h3>${state.run.skills.map(s=>`<div class="skill-row"><div><span>${esc(s.name)}</span><strong>${s.coverage}%</strong></div><div class="mini-progress"><span style="width:${s.coverage}%"></span></div></div>`).join('')}<p style="font-size:9px;color:#97aebe;margin-top:20px">Mức bao phủ thể hiện kiến thức có trong tập môn, chưa phải kết quả đánh giá năng lực cá nhân.</p></div></div>`;}
function drawChart(){if(!window.Chart)return;state.chart?.destroy();const skills=state.run.skills.slice(0,8);state.chart=new Chart($('#skill-chart'),{type:'radar',data:{labels:skills.map(s=>s.name),datasets:[{label:'Mức bao phủ trong lộ trình',data:skills.map(s=>s.coverage),borderColor:'#78a9cc',backgroundColor:'#84b3d52b',pointBackgroundColor:'#84b3d5',pointRadius:3,borderWidth:1.5}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{r:{min:0,max:100,ticks:{display:false},grid:{color:'#e6eef4'},angleLines:{color:'#e6eef4'},pointLabels:{font:{size:9,family:'Be Vietnam Pro'},color:'#92a9ba'}}}}});}
const graphKinds={Career:{label:'Nghề nghiệp',icon:'briefcase-business'},Skill:{label:'Kỹ năng',icon:'sparkles'},Course:{label:'Môn học',icon:'book-open'}};
const graphRelations={REQUIRES:'Yêu cầu kỹ năng',TEACHES:'Phát triển kỹ năng',PREREQUISITE_OF:'Là môn tiên quyết của'};
function graphWelcome(){return `<div class="graph-inspector-welcome"><span class="graph-inspector-symbol">${icon('mouse-pointer-2')}</span><h3>Khám phá từng kết nối</h3><p>Chọn một nút để tìm hiểu vai trò của môn học, kỹ năng hoặc nghề nghiệp trong hành trình của bạn.</p></div><div class="graph-tip-list"><div>${icon('circle-dot')}<p><b>Chọn nút kiến thức</b><span>Làm nổi bật các kết nối liên quan.</span></p></div><div>${icon('git-branch')}<p><b>Chọn đường nối</b><span>Xem loại quan hệ, trọng số và nguồn.</span></p></div><div>${icon('move')}<p><b>Tự do khám phá</b><span>Kéo để di chuyển, cuộn hoặc dùng nút + / − để thu phóng.</span></p></div></div>`;}
function graphView(){
  const standalone=state.page==='graph';
  return `${standalone?`<section class="graph-hero"><div class="graph-hero-copy"><span class="career-hero-eyebrow">${icon('network')}KẾT NỐI KIẾN THỨC · THẤU HIỂU HÀNH TRÌNH</span><h2>Nhìn thấy kết nối.<br><span>Hiểu rõ hướng đi.</span></h2><p>Khám phá cách những môn học hôm nay bồi đắp kỹ năng cho nghề nghiệp bạn hướng đến.</p></div><div class="graph-hero-flow" aria-label="Môn học phát triển kỹ năng, nghề nghiệp yêu cầu kỹ năng"><div class="graph-flow-step course"><span>${icon('book-open')}</span><b>Môn học</b><small>Nền tảng kiến thức</small></div><div class="graph-flow-link">${icon('arrow-right')}<small>Phát triển</small></div><div class="graph-flow-step skill"><span>${icon('sparkles')}</span><b>Kỹ năng</b><small>Năng lực chuyên môn</small></div><div class="graph-flow-link">${icon('arrow-left')}<small>Yêu cầu</small></div><div class="graph-flow-step career"><span>${icon('briefcase-business')}</span><b>Nghề nghiệp</b><small>Đích đến của bạn</small></div></div></section>`:''}
    <section class="knowledge-workspace" aria-labelledby="graph-workspace-title">
      <header class="knowledge-heading"><div><span class="career-section-kicker">BẢN ĐỒ KẾT NỐI CỦA BẠN</span><h2 id="graph-workspace-title">${esc(state.run.career_name)}</h2><p>${esc(state.run.curriculum_name)}</p></div><span class="catalog-source-label">${icon('database')}${state.curricula.find(c=>c.id===state.run.curriculum_id)?.source==='NEU'?'Danh mục NEU':'Dữ liệu minh họa'}</span></header>
      <div class="knowledge-toolbar"><div class="graph-search-wrap">${icon('search')}<input class="filter-input" id="graph-search" type="search" placeholder="Tìm môn học, kỹ năng, nghề nghiệp..." aria-label="Tìm nút đồ thị"></div><div class="graph-toolbar-actions"><button class="btn btn-white btn-small" data-action="graph-fit">${icon('scan')}Vừa màn hình</button><button class="btn btn-white btn-small" data-action="graph-reset">${icon('rotate-ccw')}Đặt lại</button></div></div>
      <div class="knowledge-layout"><div class="graph-stage"><div class="graph-stage-top"><div class="graph-legend">${Object.entries(graphKinds).map(([kind,k])=>`<span class="legend-${kind.toLowerCase()}"><b></b>${k.label} <em data-graph-count="${kind}">…</em></span>`).join('')}</div><span class="graph-edge-count" id="graph-edge-count">Đang tải kết nối…</span></div><div class="graph-canvas" id="graph-canvas" role="region" aria-label="Đồ thị kết nối môn học, kỹ năng và nghề nghiệp"></div><div class="graph-zoom-controls" role="group" aria-label="Thu phóng đồ thị"><button class="icon-button" data-action="graph-zoom-out" aria-label="Thu nhỏ đồ thị">${icon('minus')}</button><output id="graph-zoom" aria-label="Mức thu phóng">100%</output><button class="icon-button" data-action="graph-zoom-in" aria-label="Phóng to đồ thị">${icon('plus')}</button></div><div class="graph-canvas-note">${icon('hand')}Kéo để di chuyển · Chọn để khám phá</div></div><aside class="graph-inspector" aria-label="Thông tin kết nối"><div class="graph-inspector-heading">${icon('scan-search')}Thông tin kết nối</div><div class="graph-info" id="graph-info" aria-live="polite">${graphWelcome()}</div></aside></div>
      <footer class="graph-workspace-footer">${icon('info')}Đồ thị phản ánh các quan hệ kiến thức trong nguồn dữ liệu đang chọn.</footer>
    </section>`;
}
function graphNodeButton(node){const kind=graphKinds[node.data('kind')]||{label:'Kiến thức',icon:'circle-dot'};return `<button class="graph-neighbor" data-action="graph-select" data-id="${esc(node.id())}"><span class="graph-kind-icon kind-${esc(node.data('kind').toLowerCase())}">${icon(kind.icon)}</span><span>${esc(node.data('label'))}<small>${kind.label}</small></span>${icon('chevron-right')}</button>`;}
function showGraphNode(node){
  if(!node?.length||!$('#graph-info'))return;
  const kind=graphKinds[node.data('kind')]||{label:'Kiến thức',icon:'circle-dot'},neighbors=node.neighborhood('node').sort((a,b)=>a.data('label').localeCompare(b.data('label'),'vi'));
  $('#graph-info').innerHTML=`<span class="graph-selection-type kind-${esc(node.data('kind').toLowerCase())}">${icon(kind.icon)}${kind.label}</span><h3 class="graph-selection-title">${esc(node.data('label'))}</h3><p class="graph-selection-description">${node.data('kind')==='Career'?'Các kỹ năng cần phát triển để tiến gần hơn đến nghề nghiệp này.':node.data('kind')==='Skill'?'Khám phá những học phần phát triển kỹ năng này và các nghề nghiệp cần đến nó.':'Tìm hiểu những kỹ năng được phát triển qua học phần này.'}</p>${node.data('course_id')?`<button class="btn btn-primary graph-detail-button" data-action="detail" data-id="${esc(node.data('course_id'))}">Chi tiết môn học ${icon('arrow-up-right')}</button>`:''}<div class="graph-neighbor-heading">Kết nối trực tiếp <b>${neighbors.length}</b></div><div class="graph-neighbor-list">${neighbors.map(graphNodeButton).join('')||'<p class="graph-selection-description">Chưa có kết nối trực tiếp.</p>'}</div>`;icons();
}
function selectGraphNode(node){if(!node?.length)return;state.graph.elements().removeClass('dim highlight').addClass('dim');node.closedNeighborhood().removeClass('dim');node.connectedEdges().addClass('highlight');node.addClass('highlight');showGraphNode(node);}
function resetGraph(){if(!state.graph)return;state.graph.elements().unselect().removeClass('dim highlight');if($('#graph-search'))$('#graph-search').value='';if($('#graph-info'))$('#graph-info').innerHTML=graphWelcome();state.graph.fit(undefined,40);icons();}
function searchGraph(value){
  if(!state.graph)return;
  const q=value.toLocaleLowerCase('vi').trim();
  state.graph.elements().removeClass('dim highlight');
  if(!q){$('#graph-info').innerHTML=graphWelcome();icons();return;}
  const matches=state.graph.nodes().filter(n=>n.data('label').toLocaleLowerCase('vi').includes(q));
  state.graph.elements().addClass('dim');matches.closedNeighborhood().removeClass('dim');matches.addClass('highlight');
  $('#graph-info').innerHTML=`<span class="graph-selection-type">${icon('search')}Kết quả tìm kiếm</span><h3 class="graph-selection-title">${matches.length} kết quả</h3><p class="graph-selection-description">${matches.length?'Chọn một kết quả để khám phá các kết nối.':'Chưa tìm thấy nút phù hợp. Thử tên môn học hoặc kỹ năng khác.'}</p><div class="graph-neighbor-list">${matches.map(graphNodeButton).join('')}</div>`;icons();
}
async function drawGraph(courseId){
  const data=await api(`/graph?career_id=${encodeURIComponent(state.run.career_id)}&curriculum_id=${encodeURIComponent(state.run.curriculum_id)}`);
  if(!$('#graph-canvas'))return;
  if(!window.cytoscape){toast('Không tải được thư viện đồ thị. Vui lòng tải lại trang.',true);return;}
  state.graph?.destroy();
  state.graph=cytoscape({container:$('#graph-canvas'),elements:[...data.nodes,...data.edges],style:[
    {selector:'node',style:{label:'data(label)','font-family':'Be Vietnam Pro','font-size':12,'text-valign':'bottom','text-margin-y':8,'text-wrap':'wrap','text-max-width':112,'background-color':'#6d98c6',width:28,height:28,color:'#42617b','border-width':4,'border-color':'#e9f1fa','text-background-color':'#ffffff','text-background-opacity':.85,'text-background-padding':2,'text-background-shape':'roundrectangle'}},
    {selector:'node[kind="Career"]',style:{'background-color':'#00558f','border-color':'#d9ebf8',width:52,height:52,'font-weight':600,'font-size':14,color:'#00558f'}},
    {selector:'node[kind="Skill"]',style:{'background-color':'#269ba6','border-color':'#dff3f2',width:25,height:25}},
    {selector:'edge',style:{width:1.2,'line-color':'#c4d8e8','target-arrow-color':'#acc8dc','target-arrow-shape':'triangle','arrow-scale':.7,'curve-style':'bezier',opacity:.75}},
    {selector:'.dim',style:{opacity:.12}},
    {selector:'edge.highlight',style:{'line-color':'#207fb5','target-arrow-color':'#207fb5',width:2.5,opacity:1}},
    {selector:'node.highlight',style:{'border-color':'#9acbed','border-width':6,'font-weight':600}},
    {selector:'node:selected',style:{'border-color':'#9acbed'}},
    {selector:'edge:selected',style:{'line-color':'#00558f','target-arrow-color':'#00558f',width:3}}
  ],layout:{name:'concentric',animate:false,concentric:node=>({Career:3,Skill:2,Course:1})[node.data('kind')]||1,levelWidth:()=>1,minNodeSpacing:50,spacingFactor:1.05,avoidOverlap:true,padding:40},minZoom:.1,maxZoom:3});
  for(const [kind] of Object.entries(graphKinds)){const label=$(`[data-graph-count="${kind}"]`);if(label)label.textContent=data.nodes.filter(n=>n.data.kind===kind).length;}
  $('#graph-edge-count').textContent=data.edges.length+' quan hệ';
  const updateZoom=()=>{if($('#graph-zoom'))$('#graph-zoom').textContent=Math.round(state.graph.zoom()*100)+'%';};
  state.graph.on('zoom',updateZoom);updateZoom();
  state.graph.on('tap','node',evt=>selectGraphNode(evt.target));
  state.graph.on('tap','edge',evt=>{
    const edge=evt.target;state.graph.elements().removeClass('dim highlight').addClass('dim');edge.connectedNodes().union(edge).removeClass('dim').addClass('highlight');
    $('#graph-info').innerHTML=`<span class="graph-selection-type">${icon('git-branch')}Quan hệ kiến thức</span><h3 class="graph-selection-title">${esc(graphRelations[edge.data('relation')]||edge.data('relation'))}</h3><div class="graph-edge-path"><span>${esc(edge.source().data('label'))}</span>${icon('arrow-down')}<span>${esc(edge.target().data('label'))}</span></div><dl class="graph-edge-facts"><div><dt>Loại quan hệ</dt><dd>${esc(edge.data('relation'))}</dd></div><div><dt>Trọng số</dt><dd>${esc(edge.data('weight'))}</dd></div><div><dt>Tin cậy</dt><dd>${Math.round(edge.data('confidence')*100)}%</dd></div></dl><div class="graph-source-note">${icon('database')}<div><b>Nguồn:</b><p>${esc(edge.data('provenance'))}</p></div></div>`;icons();
  });
  state.graph.on('tap',evt=>{if(evt.target===state.graph)resetGraph();});
  if(courseId)highlightCourse(courseId);
}
function highlightCourse(courseId){if(!state.graph)return;const node=state.graph.getElementById('course:'+courseId);if(node.length){state.graph.elements().addClass('dim').removeClass('highlight');const skills=node.outgoers('node'),path=node.closedNeighborhood().union(skills.incomers());path.removeClass('dim').addClass('highlight');state.graph.fit(path,65);showGraphNode(node);}}
function renderRoadmap(){const view=$('#view-content');view.innerHTML=hero()+stats()+tabs()+`<div id="tab-content">${state.tab==='timeline'?timeline():state.tab==='recommendations'?recommendationList():state.tab==='graph'?graphView():skillsView()}</div>`;icons();if(state.tab==='graph')drawGraph().catch(e=>toast(e.message,true));if(state.tab==='skills')drawChart();}
async function generate(inputs){const result=await api('/recommendations',{method:'POST',body:JSON.stringify(inputs)});state.run=result;localStorage.setItem('neu-run',result.run_id);localStorage.setItem('neu-inputs',JSON.stringify(inputs));return result;}
async function defaultRun(){let saved;try{saved=JSON.parse(localStorage.getItem('neu-inputs'));}catch{}const inputs=saved&&state.curricula.some(c=>c.id===saved.curriculum_id)?saved:{curriculum_id:'DEMO-7480201-K66',career_id:'backend',current_semester:3};await generate(inputs);}
function createModal(careerId){const r=state.run;const current=state.curricula.find(c=>c.id===r?.curriculum_id);openModal('Thiết kế hành trình của bạn','Chọn chương trình và đích đến, phần còn lại để chúng mình kết nối.',`<form id="create-form"><div class="field"><label for="source-input">Nguồn chương trình</label><select id="source-input" name="source"><option value="DEMO">Dữ liệu minh họa · sẵn sàng trải nghiệm</option><option value="NEU">Chương trình NEU · cần xác minh nhóm tự chọn</option></select></div><div class="form-grid"><div class="field"><label for="major-input">Ngành / chương trình</label><select id="major-input" name="major_id">${state.majors.map(m=>option(m.id,m.name,current?.major_id||'7480201')).join('')}</select></div><div class="field"><label for="cohort-input">Khóa tuyển sinh</label><select id="cohort-input" name="cohort">${['K65 - 2023','K66 - 2024','K67 - 2025','K68 - 2026'].map(c=>option(c,c,current?.cohort||'K66 - 2024')).join('')}</select></div><div class="field"><label for="career-input">Nghề nghiệp mục tiêu</label><select id="career-input" name="career_id">${state.careers.map(c=>option(c.id,c.name,careerId||r?.career_id||'backend')).join('')}</select></div><div class="field"><label for="semester-input">Học kỳ hiện tại</label><select id="semester-input" name="current_semester">${Array.from({length:10},(_,i)=>option(String(i+1),'Học kỳ '+(i+1),String(r?Math.min(...chosen().map(c=>c.proposed_semester)):3))).join('')}</select></div></div><div class="field" style="margin-top:18px"><label for="interests-input">Kỹ năng bạn quan tâm (không bắt buộc)</label><select id="interests-input" name="interests"><option value="">Để hệ thống gợi ý theo nghề nghiệp</option><option value="python">Python</option><option value="data">Phân tích dữ liệu</option><option value="security">Bảo mật thông tin</option><option value="web">Phát triển web</option><option value="ui">Thiết kế giao diện</option></select></div><div class="demo-callout">${icon('info')}<span>Dữ liệu minh họa – không phải chương trình đào tạo chính thức. Quy tắc 10/15 chỉ đang áp dụng cho bộ dữ liệu demo; nhóm môn NEU cần được xác minh theo từng chương trình và khóa.</span></div><div class="form-error"></div></form>`,`<button class="btn btn-white" data-action="close">Để sau</button><button class="btn btn-primary" type="submit" form="create-form">${icon('sparkles')}Tạo lộ trình của tôi</button>`);}
async function authModal(register=false){
  const accounts=register?[]:await demoAccountsPromise;
  const demo=accounts.length?`<section class="demo-login-panel" aria-label="Tài khoản demo"><div class="demo-login-title">${icon('presentation')}Sẵn sàng trải nghiệm</div><p>Chọn tài khoản mẫu để điền nhanh thông tin đăng nhập.</p><div class="demo-account-grid">${accounts.map(a=>`<article class="demo-account-card"><div class="demo-account-role">${icon(a.role==='admin'?'shield-check':'graduation-cap')}<b>${esc(a.label)}</b></div><dl><div><dt>Email</dt><dd>${esc(a.email)}</dd></div><div><dt>Mật khẩu</dt><dd><code>${esc(a.password)}</code></dd></div></dl><button class="btn btn-white btn-small" type="button" data-action="demo-fill" data-id="${esc(a.key)}" aria-label="Dùng tài khoản ${esc(a.label)}">Dùng tài khoản ${icon('arrow-up-right')}</button></article>`).join('')}</div><small>Thông tin công khai dành riêng cho bản demo khách hàng.</small></section>`:'';
  openModal(register?'Tạo tài khoản học tập':'Chào mừng bạn trở lại',register?'Lưu hành trình và theo dõi từng bước tiến của bạn.':'Đăng nhập để lưu lộ trình và cập nhật tiến độ học tập.',`${demo}<form class="auth-form" id="auth-form" data-register="${register}">${register?'<div class="field"><label for="auth-name">Họ và tên</label><input id="auth-name" name="name" required maxlength="100" placeholder="Nguyễn Minh Anh" autocomplete="name"></div>':''}<div class="field"><label for="auth-email">Email</label><input id="auth-email" name="email" required type="email" maxlength="254" placeholder="ban@st.neu.edu.vn" autocomplete="email"></div><div class="field"><label for="auth-password">Mật khẩu</label><input id="auth-password" name="password" required type="password" minlength="8" maxlength="128" placeholder="Tối thiểu 8 ký tự" autocomplete="${register?'new-password':'current-password'}"></div><div class="form-error"></div><button class="btn btn-primary" type="submit">${register?'Tạo tài khoản':'Đăng nhập'}${icon('arrow-right')}</button></form><div class="auth-switch">${register?'Đã có tài khoản?':'Chưa có tài khoản?'}<button class="btn btn-link" data-action="${register?'login':'register'}">${register?'Đăng nhập':'Đăng ký ngay'}</button></div>`);
}
async function finishAuthentication(user){
  state.auth=true;
  const [progress,profile]=await Promise.all([api('/progress'),api('/profile')]);
  state.progress=Object.fromEntries(progress.map(p=>[p.course_id,p.status]));state.user=profile;
  if(state.pending){
    $('.user-info').innerHTML=esc(user.name)+'<small>'+(user.role==='admin'?'Quản trị hệ thống':'Sinh viên NEU')+'</small>';
    $('.avatar').textContent=user.name.slice(0,1).toUpperCase();
    const pending=state.pending;state.pending=null;closeModal();
    if(pending==='save')await saveModal();else if(pending.startsWith('detail:'))await showDetail(pending.slice(7));
    toast('Đăng nhập thành công.');return;
  }
  // Account switches should open this account's saved work rather than a previous visitor's run.
  localStorage.removeItem('neu-run');localStorage.removeItem('neu-inputs');
  sessionStorage.removeItem('neu-load-saved');sessionStorage.removeItem('neu-graph-course');
  const paths=await api('/roadmaps');
  if(paths.length){localStorage.setItem('neu-run',paths[0].run_id);sessionStorage.setItem('neu-load-saved','true');}
  window.location.href=user.role==='admin'?'/admin':'/dashboard';
}
async function showDetail(id){const course=state.run?.items.find(c=>c.id===id)||await api('/courses/'+encodeURIComponent(id));const detail=course.detail||{};openModal(course.name,`${course.code} · ${course.source==='DEMO'?'Học phần minh họa':'Danh mục NEU'}`,`${cover(course,true)}<div class="detail-meta"><span>${course.credits!=null?course.credits+' tín chỉ':'Chưa xác minh tín chỉ'}</span><span>·</span><span>${course.proposed_semester?'Học kỳ '+course.proposed_semester+' dự kiến':'Chưa có kế hoạch học kỳ'}</span></div><div class="detail-section"><h3>Giới thiệu học phần</h3><p>${esc(course.description||'API tìm kiếm chưa cung cấp mô tả. Cần bổ sung ID đề cương đã xác minh.')}</p></div>${course.reason?`<div class="detail-section"><h3>Vì sao học phần này phù hợp?</h3><p>${esc(course.reason)}</p></div>`:''}${course.paths?.length?`<div class="detail-section"><h3>Kết nối trong đồ thị tri thức</h3>${course.paths.slice(0,3).map(p=>`<div class="path-line">${esc(p.labels[0])} <b>→ yêu cầu →</b> ${esc(p.labels[1])} <b>← được dạy bởi ←</b> ${esc(p.labels[2])}</div>`).join('')}<button class="btn btn-link" data-action="show-path" data-id="${esc(id)}">Xem trên đồ thị ${icon('arrow-up-right')}</button></div>`:''}${course.components?`<div class="detail-section"><h3>Thành phần điểm phù hợp</h3>${Object.entries(course.components).map(([k,v])=>`<div class="lesson-row"><span>${({skills:'Đáp ứng kỹ năng (45%)',topics:'Chủ đề kiến thức (25%)',graph:'Quan hệ trong đồ thị (15%)',foundation:'Kiến thức nền (10%)',interests:'Sở thích cá nhân (5%)'})[k]}</span><span>${v}/100</span></div>`).join('')}</div>`:''}<div class="detail-section"><h3>Môn tiên quyết</h3><p>${(course.prerequisites||detail.prerequisites||[]).length?(course.prerequisites||detail.prerequisites).map(p=>esc(state.run?.items.find(c=>c.id===p)?.name||p)).join(', '):course.source==='DEMO'?'Không có trong bộ dữ liệu minh họa.':'Chưa được xác minh từ đề cương.'}</p>${course.missing_prerequisites?.length?'<p style="color:#b59764;margin-top:5px">Chưa đủ điều kiện đăng ký ngay. Cần hoàn thành môn tiên quyết trước.</p>':''}</div>${detail.outcomes?.length?`<div class="detail-section"><h3>Chuẩn đầu ra minh họa</h3><ul>${detail.outcomes.map(o=>`<li>${esc(o)}</li>`).join('')}</ul></div>`:''}${detail.lessons?.length?`<div class="detail-section"><h3>Nội dung và kế hoạch giảng dạy mẫu</h3>${detail.lessons.map((l,i)=>`<div class="lesson-row"><span>${i+1}. ${esc(l.title)}</span><span>${l.hours} tiết</span></div>`).join('')}</div>`:''}<div class="detail-section"><h3>Cập nhật tiến độ của bạn</h3><div class="status-controls">${Object.entries(statusLabels).map(([s,label])=>`<button class="btn ${statusOf(id)===s?'btn-primary':'btn-white'} btn-small" data-action="progress" data-id="${esc(id)}" data-status="${s}">${statusOf(id)===s?icon('check'):''}${label}</button>`).join('')}</div></div><div class="demo-callout">${icon('info')}${esc(detail.source_note||'Nguồn: bộ dữ liệu demo-expert-v1, quan hệ được cấu hình phục vụ minh họa thuật toán.')}</div>`,`<button class="btn btn-white" data-action="close">Đóng chi tiết</button>`);}
