const careerPhotoBase=new URL('../images/careers/',(document.currentScript||$('script[src*="/static/js/app.js"]')).src).href;
function careerStory(career){return careerStories[career.id]||{group:'software',photo:'team.webp',summary:career.description,alt:'Nhóm đồng nghiệp làm việc cùng máy tính'};}
function careerPhoto(career){return new URL(careerStory(career).photo,careerPhotoBase).href+'?v=careers-1';}
function normalizeCareerSearch(text){return String(text||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').toLowerCase().trim();}
function careerPhotoCard(c){
  const story=careerStory(c),group=careerGroups[story.group];
  return `<article class="career-card career-photo-card" data-group="${story.group}" data-search="${esc(normalizeCareerSearch(c.name+' '+c.english+' '+c.skills.map(s=>s.name).join(' ')))}"><div class="career-card-photo"><img class="career-photo" src="${esc(careerPhoto(c))}" alt="${esc(story.alt)}" width="1000" height="650" loading="lazy" decoding="async" style="object-position:${story.position||'50% 50%'}"><span class="career-photo-tint" aria-hidden="true"></span><span class="career-category-label">${icon(group.icon)}${group.label}</span><span class="career-card-icon">${icon(c.icon)}</span></div><div class="career-card-body"><h3>${esc(c.name)}</h3><span class="career-english">${esc(c.english)}</span><p class="career-summary">${esc(story.summary)}</p><div class="skill-tags career-skills">${c.skills.slice(0,4).map(s=>`<span>${esc(s.name)}</span>`).join('')}</div></div><div class="career-card-footer"><button class="career-detail-link" data-action="career-detail" data-id="${esc(c.id)}">Tìm hiểu nghề ${icon('arrow-up-right')}</button><button class="btn btn-primary" data-action="select-career" data-id="${esc(c.id)}">Chọn định hướng ${icon('arrow-right')}</button></div></article>`;
}
function careerCatalog(){
  state.careerGroup='all';
  const groupCount=Object.keys(careerGroups).filter(key=>state.careers.some(c=>careerStory(c).group===key)).length;
  $('#view-content').innerHTML=`<section class="career-hero"><div class="career-hero-content"><span class="career-hero-eyebrow">${icon('compass')}TỪ ĐAM MÊ ĐẾN NGHỀ NGHIỆP</span><h2>Chọn nghề bạn yêu.<br><span>Học đúng điều bạn cần.</span></h2><p>Mỗi đích đến đều có một hành trình riêng. Khám phá các lĩnh vực công nghệ và tìm hướng đi phù hợp với bạn.</p><div class="career-hero-facts"><span>${icon('briefcase-business')}<b>${state.careers.length}</b> định hướng</span><span>${icon('layers')}<b>${groupCount}</b> nhóm lĩnh vực</span><span>${icon('route')}Lộ trình cá nhân hóa</span></div></div><div class="career-hero-visual"><img src="${esc(careerPhotoBase+'team.webp')}" alt="Nhóm đồng nghiệp cùng trao đổi và làm việc với máy tính" width="1200" height="800" fetchpriority="high"><span class="career-hero-blend" aria-hidden="true"></span><div class="career-hero-caption"><span>${icon('sparkles')}</span><div>Hành trình của riêng bạn<small>Bắt đầu từ một định hướng rõ ràng</small></div></div></div></section><section class="career-explore" aria-labelledby="career-section-title"><div class="career-explore-top"><div><div class="career-section-kicker">KHÁM PHÁ CƠ HỘI</div><h2 id="career-section-title">Bạn muốn trở thành ai?</h2></div><div class="career-search-box">${icon('search')}<input class="filter-input" id="career-search" placeholder="Tìm nghề nghiệp hoặc kỹ năng..." aria-label="Tìm nghề nghiệp"><button class="icon-button" id="career-search-clear" data-action="career-clear" aria-label="Xóa nội dung tìm kiếm" hidden>${icon('x')}</button></div></div><div class="career-filter-row"><div class="career-filters" role="group" aria-label="Lọc nhóm nghề nghiệp"><button class="career-filter active" data-action="career-filter" data-id="all" aria-pressed="true">Tất cả<span>${state.careers.length}</span></button>${Object.entries(careerGroups).map(([key,g])=>`<button class="career-filter" data-action="career-filter" data-id="${key}" aria-pressed="false">${icon(g.icon)}${g.label}</button>`).join('')}</div><span class="career-result-count" id="career-result-count">${state.careers.length} định hướng</span></div><div class="career-catalog-grid" id="career-grid">${state.careers.map(careerPhotoCard).join('')}</div><div id="career-empty" hidden>${empty('Chưa tìm thấy nghề nghiệp phù hợp','Thử một từ khóa khác hoặc khám phá lại tất cả các lĩnh vực.','search',`<button class="btn btn-white" data-action="career-reset">Hiển thị tất cả định hướng ${icon('arrow-right')}</button>`)}</div><div class="career-bottom-note">${icon('compass')}Bạn có thể khám phá nhiều hướng đi và thay đổi mục tiêu khi hiểu rõ hơn về bản thân.</div></section>`;
  icons();
}
function filterCareerCards(){
  const search=$('#career-search');if(!search)return;
  const query=normalizeCareerSearch(search.value),group=state.careerGroup||'all';
  let count=0;
  $$('#career-grid .career-card').forEach(card=>{card.hidden=!(card.dataset.search.includes(query)&&(group==='all'||card.dataset.group===group));if(!card.hidden)count++;});
  $('#career-result-count').textContent=count+' định hướng';
  $('#career-empty').hidden=count>0;
  $('#career-search-clear').hidden=!search.value;
  $$('.career-filter').forEach(button=>{const selected=button.dataset.id===group;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected));});
}
function careerDetails(id){
  const c=state.careers.find(c=>c.id===id);if(!c)return;
  const story=careerStory(c),group=careerGroups[story.group];
  openModal(c.name,c.english,`<div class="career-detail-photo"><img src="${esc(careerPhoto(c))}" alt="${esc(story.alt)}" style="object-position:${story.position||'50% 50%'}"></div><span class="career-detail-category">${icon(group.icon)}${group.label}</span><div class="detail-section"><h3>Công việc này có gì thú vị?</h3><p>${esc(story.summary)}</p></div><div class="detail-section"><h3>Những kỹ năng bạn sẽ phát triển</h3><div class="skill-tags career-detail-skills">${c.skills.map(s=>`<span>${esc(s.name)}</span>`).join('')}</div></div><div class="career-detail-next">${icon('route')}<div><h3>Từ định hướng đến hành trình học tập</h3><p>Chọn nghề này để xem các học phần, kỹ năng và thứ tự học phù hợp với chương trình của bạn.</p></div></div>`,`<button class="btn btn-white" data-action="close">Để sau</button><button class="btn btn-primary" data-action="select-career" data-id="${esc(c.id)}">Chọn định hướng ${icon('arrow-right')}</button>`);
}
async function savedView(){if(!state.auth){$('#view-content').innerHTML=empty('Hành trình của bạn bắt đầu tại đây','Đăng nhập để lưu nhiều lộ trình, theo dõi tiến độ và so sánh các định hướng.','bookmark',`<button class="btn btn-primary" data-action="login">Đăng nhập để tiếp tục ${icon('arrow-right')}</button>`);icons();return;}const paths=await api('/roadmaps');$('#view-content').innerHTML=paths.length?`<div class="catalog-grid">${paths.map(p=>`<article class="saved-card"><span class="target-icon">${icon('route')}</span><h3 style="margin-top:14px">${esc(p.name)}</h3><p>${esc(p.career)}<br>${new Date(p.created_at+'Z').toLocaleDateString('vi-VN')} · 10 học phần</p><div class="saved-actions"><button class="btn btn-primary btn-small" data-action="load-saved" data-id="${p.run_id}">Tiếp tục ${icon('arrow-right')}</button><button class="icon-button" data-action="rename" data-id="${p.id}" data-name="${esc(p.name)}" aria-label="Đổi tên lộ trình">${icon('pencil')}</button><button class="icon-button" data-action="delete-saved" data-id="${p.id}" aria-label="Xóa lộ trình">${icon('trash-2')}</button></div></article>`).join('')}</div>`:empty('Chưa có lộ trình được lưu','Khám phá một định hướng nghề nghiệp, tạo hành trình riêng và lưu lại để tiếp tục vào lần sau.','bookmark',`<button class="btn btn-primary" data-action="create">${icon('plus')}Tạo lộ trình đầu tiên</button>`);icons();}
async function profileView(){
 if(!state.auth){$('#view-content').innerHTML=empty('Một hồ sơ, một hành trình riêng','Đăng nhập để quản lý thông tin, cập nhật kỹ năng và xem tiến độ học tập.','user-round',`<button class="btn btn-primary" data-action="login">Đăng nhập</button>`);icons();return;}
 const user=await api('/profile');
 $('#view-content').innerHTML=`<div class="profile-panel"><h3>Thông tin cá nhân</h3><form id="profile-form"><div class="field"><label for="profile-name">Họ và tên</label><input id="profile-name" name="name" value="${esc(user.name)}" required maxlength="100"></div><div class="field"><label>Email</label><input value="${esc(user.email)}" readonly></div><div class="form-grid"><div class="field"><label for="profile-major">Ngành / chương trình</label><select id="profile-major" name="major_id">${state.majors.map(m=>option(m.id,m.name,user.profile?.major_id||'7480201')).join('')}</select></div><div class="field"><label for="profile-cohort">Khóa tuyển sinh</label><select id="profile-cohort" name="cohort">${['K65 - 2023','K66 - 2024','K67 - 2025','K68 - 2026'].map(c=>option(c,c,user.profile?.cohort||'K66 - 2024')).join('')}</select></div></div><div class="field" style="margin-top:20px"><label for="profile-career">Nghề nghiệp mục tiêu</label><select id="profile-career" name="career_id">${state.careers.map(c=>option(c.id,c.name,user.profile?.career_id||state.run.career_id)).join('')}</select></div><button class="btn btn-primary" type="submit">${icon('save')}Lưu thông tin</button></form><hr><h3>Đổi mật khẩu</h3><form id="password-form"><div class="field"><label for="old-password">Mật khẩu hiện tại</label><input type="password" id="old-password" name="old_password" required autocomplete="current-password"></div><div class="field"><label for="new-password">Mật khẩu mới</label><input type="password" id="new-password" name="password" required minlength="8" maxlength="128" autocomplete="new-password"></div><button class="btn btn-white" type="submit">${icon('lock-keyhole')}Cập nhật mật khẩu</button></form><hr><button class="btn btn-danger" data-action="logout">${icon('log-out')}Đăng xuất tài khoản</button></div>`;icons();
}
async function saveModal(){if(!requireAuth('save'))return;openModal('Lưu hành trình của bạn','Lưu lộ trình để quay lại học bất cứ lúc nào.',`<form id="save-form"><div class="field"><label for="path-name">Tên lộ trình</label><input id="path-name" name="name" maxlength="150" required value="${esc(state.run.career_english+' · '+state.run.cohort)}"></div><div class="form-error"></div></form>`,`<button class="btn btn-white" data-action="close">Để sau</button><button type="submit" form="save-form" class="btn btn-primary">${icon('bookmark')}Lưu lộ trình</button>`);}
async function compareModal(){openModal('So sánh hai định hướng','Khám phá điểm giao nhau và những kiến thức khác biệt.',`<div class="field"><label for="compare-career">Nghề nghiệp muốn so sánh với ${esc(state.run.career_english)}</label><select id="compare-career">${state.careers.filter(c=>c.id!==state.run.career_id).map(c=>option(c.id,c.name,'frontend')).join('')}</select></div><div id="comparison-content"><p style="font-size:10px;color:#98afc0">Chọn định hướng và nhấn so sánh để xem hai tập môn được tối ưu độc lập.</p></div>`,`<button class="btn btn-white" data-action="close">Đóng</button><button class="btn btn-primary" data-action="run-compare">${icon('git-compare-arrows')}So sánh lộ trình</button>`,true);}
async function runComparison(){const id=$('#compare-career').value;$('#comparison-content').innerHTML='<div class="loading-state" style="min-height:150px"><span class="spinner"></span>Đang đối chiếu hai định hướng...</div>';const other=await api('/recommendations',{method:'POST',body:JSON.stringify({curriculum_id:state.run.curriculum_id,career_id:id,current_semester:3})});const original=chosen(),alternative=other.items.filter(c=>c.selected),overlap=original.filter(c=>alternative.some(a=>a.id===c.id)).length;$('#comparison-content').innerHTML=`<div class="demo-callout" style="margin-bottom:20px">${icon('git-compare-arrows')}${overlap} học phần chung · ${10-overlap} học phần khác nhau cho mỗi định hướng.</div><div class="compare-grid">${[[state.run,original,alternative],[other,alternative,original]].map(([r,list,opposite])=>`<div><h3>${esc(r.career_english)}<small style="font-size:9px;font-weight:400;margin-top:5px">Bao phủ kỹ năng: ${r.coverage}%</small></h3>${list.map(c=>`<div class="compare-course ${opposite.some(a=>a.id===c.id)?'':'changed'}">${esc(c.name)} · ${c.score}%</div>`).join('')}</div>`).join('')}</div>`;icons();}
const adminLabels={careers:'Nghề nghiệp',skills:'Kỹ năng',curricula:'Chương trình',majors:'Ngành học',courses:'Môn học',nodes:'Nút đồ thị',edges:'Quan hệ',users:'Người dùng',sync:'Đồng bộ dữ liệu',weights:'Trọng số'};
async function adminView(kind=state.adminKind){state.adminKind=kind;const stats=await api('/admin/stats');$('#view-content').innerHTML=`<div class="stats-row"><div class="stat"><span class="stat-icon primary">${icon('users')}</span><div><small>Người dùng</small><strong>${stats.users}</strong></div></div><div class="stat"><span class="stat-icon blue">${icon('book-open')}</span><div><small>Môn học</small><strong>${stats.courses}</strong></div></div><div class="stat"><span class="stat-icon green">${icon('network')}</span><div><small>Nút / quan hệ</small><strong>${stats.nodes}<span>/ ${stats.edges}</span></strong></div></div><div class="stat"><span class="stat-icon orange">${icon('shield-check')}</span><div><small>Quan hệ chờ duyệt</small><strong>${stats.pending_edges}</strong></div></div></div><div class="admin-tabs">${Object.entries(adminLabels).map(([key,label])=>`<button class="btn btn-white btn-small ${kind===key?'active':''}" data-action="admin-kind" data-id="${key}">${label}</button>`).join('')}</div><div class="admin-header"><h3>${adminLabels[kind]}</h3>${!['sync','weights','users','courses'].includes(kind)?`<button class="btn btn-primary btn-small" data-action="admin-add">${icon('plus')}Thêm mới</button>`:''}</div><div id="admin-content"></div><div class="demo-callout">${icon('info')}Kiểm tra đồ thị: ${stats.cycles.length} chu trình tiên quyết · ${stats.isolated.length} nút cô lập · ${stats.components} thành phần liên thông. Ngành/chương trình chỉ được xác nhận sau khi đối chiếu dữ liệu theo khóa.</div>`;if(kind==='weights'){$('#admin-content').innerHTML=`<div class="profile-panel"><p style="font-size:10px;color:#91a9bb;margin-bottom:15px">Điều chỉnh năm trọng số. Các giá trị nằm trong khoảng 0–1 và có tổng bằng 1.</p><form id="weights-form">${Object.entries(stats.weights).map(([k,v])=>`<div class="field"><label>${({skills:'Kỹ năng nghề nghiệp',topics:'Chủ đề kiến thức',graph:'Đường đi đồ thị',foundation:'Kiến thức nền',interests:'Sở thích cá nhân'})[k]}</label><input type="number" name="${k}" value="${v}" min="0" max="1" step="0.01" required></div>`).join('')}<button class="btn btn-primary" type="submit">Lưu trọng số</button></form></div>`;}else if(kind==='sync'){const jobs=await api('/admin/sync/status');$('#admin-content').innerHTML=`<form class="filter-bar" id="sync-form"><select class="filter-input" name="kind" aria-label="Loại dữ liệu đồng bộ"><option value="courses">Danh mục môn học</option><option value="curricula">5 chương trình NEU</option></select><select class="filter-input" name="cohort" aria-label="Khóa đồng bộ"><option>K66 - 2024</option><option>K65 - 2023</option><option>K67 - 2025</option><option>K68 - 2026</option></select><input class="filter-input" name="q" value="lập trình" required maxlength="100" aria-label="Từ khóa đồng bộ"><button class="btn btn-primary" type="submit">${icon('refresh-cw')}Đồng bộ API NEU</button></form><p style="font-size:10px;color:#96adbe;margin-bottom:15px">Đồng bộ tên, mã và danh sách khóa có trong kết quả tìm kiếm. Không tự suy diễn tín chỉ, kỹ năng hoặc nhóm môn tự chọn.</p><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Lần chạy</th><th>Trạng thái</th><th>Nguồn</th><th>Số môn</th><th>Chi tiết</th></tr></thead><tbody>${jobs.map(j=>`<tr><td>#${j.id}</td><td>${j.status==='success'?'Thành công':'Lỗi nguồn · giữ cache'}</td><td>${esc(j.source)}</td><td>${j.records}</td><td title="${esc(JSON.stringify(j.detail))}">${esc(j.detail.error||j.detail.note||'Đã đồng bộ')}</td></tr>`).join('')}</tbody></table></div>`;}else{const rows=await api('/admin/'+kind);state.adminRows=rows;const columns=rows.length?Object.keys(rows[0]).filter(k=>!['detail','properties','profile','aliases'].includes(k)).slice(0,5):['id','name'];$('#admin-content').innerHTML=`<div class="data-table-wrap"><table class="data-table"><thead><tr>${columns.map(c=>`<th>${esc(c)}</th>`).join('')}<th>Thao tác</th></tr></thead><tbody>${rows.map((row,i)=>`<tr>${columns.map(c=>`<td title="${esc(typeof row[c]==='object'?JSON.stringify(row[c]):row[c])}">${esc(typeof row[c]==='boolean'?(row[c]?'Đã xác nhận':'Chưa xác nhận'):typeof row[c]==='object'?JSON.stringify(row[c]):row[c])}</td>`).join('')}<td><button class="btn btn-link" data-action="admin-edit" data-id="${i}">Chỉnh sửa</button>${kind==='curricula'?`<button class="btn btn-link" style="margin-left:10px" data-action="membership" data-id="${esc(row.id)}">Nhóm học phần</button>`:''}${kind==='courses'&&row.source==='NEU'?`<button class="btn btn-link" style="margin-left:10px" data-action="syllabus-sync" data-id="${esc(row.id)}">Đề cương</button>`:''}${!['courses','curricula','majors','nodes','users'].includes(kind)?`<button class="btn btn-link" style="color:#bc8594;margin-left:12px" data-action="admin-delete" data-id="${esc(row.id)}">Xóa</button>`:''}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty-state" style="min-height:170px">Chưa có dữ liệu. Hãy thêm bản ghi đầu tiên.</div>':''}</div>`;}icons();}
function adminEditor(index){const kind=state.adminKind;let record=index==null?({careers:{id:'',name:'',english:'',description:'',icon:'code-xml'},skills:{id:'',name:'',aliases:[]},majors:{id:'',name:'',confirmed:false},curricula:{id:'',major_id:'7480201',cohort:'K66 - 2024',name:'',source:'NEU',elective_count:null,choose_count:null,verified:false},nodes:{id:'',kind:'Skill',label:'',properties:{}},edges:{source_id:'',target_id:'',relation:'TEACHES',weight:1,provenance:'Bổ sung thủ công: cần ghi tài liệu nguồn',confidence:1,approved:false}})[kind]:{...state.adminRows[index]};const id=index==null?null:record.id;if(id!==null)delete record.id;if(kind==='users')record={name:record.name,role:record.role};if(kind==='courses')record={name:record.name,description:record.description,credits:record.credits,syllabus_id:record.syllabus_id,detail:record.detail};openModal(index==null?'Thêm '+adminLabels[kind].toLowerCase():'Chỉnh sửa '+adminLabels[kind].toLowerCase(),'Dữ liệu được kiểm tra và lưu trực tiếp vào SQLite.',`<form id="admin-editor-form" data-id="${esc(id??'')}" data-kind="${kind}"><div class="field"><label for="record-json">Thông tin bản ghi (JSON)</label><textarea id="record-json" name="json" class="json-editor" required spellcheck="false">${esc(JSON.stringify(record,null,2))}</textarea><small>Quan hệ suy luận cần approved: false trước khi kiểm duyệt. Mỗi cạnh cần có provenance ghi nguồn bằng chứng.</small></div><div class="form-error"></div></form>`,`<button class="btn btn-white" data-action="close">Hủy</button><button class="btn btn-primary" type="submit" form="admin-editor-form">${icon('save')}Lưu thay đổi</button>`);}
function welcome(){return `<section class="welcome-block"><span class="hero-pill">${icon('sparkles')}HÀNH TRÌNH CỦA RIÊNG BẠN</span><h2 style="margin-top:15px">Học đúng hướng.<br><span>Chạm đến tương lai.</span></h2><p>Kết nối những môn học hôm nay với nghề nghiệp ngày mai. Khám phá lộ trình phù hợp với ngành học, mục tiêu và thế mạnh của bạn.</p><button class="btn btn-primary" data-action="create">Khám phá lộ trình ${icon('arrow-right')}</button></section><div class="welcome-steps">${[['graduation-cap','01 · Chọn ngành học','Bắt đầu từ chương trình và khóa tuyển sinh của bạn.'],['briefcase-business','02 · Chọn đích đến','Tìm nghề nghiệp phù hợp với điều bạn yêu thích.'],['route','03 · Nhận lộ trình','Kết nối môn học, kỹ năng và thứ tự học phù hợp.']].map(([ic,title,desc])=>`<article class="welcome-step"><span class="target-icon">${icon(ic)}</span><h3>${title}</h3><p>${desc}</p></article>`).join('')}</div>`;}
async function renderPage(){if(state.page==='roadmap'||state.page==='dashboard'){renderRoadmap();if(state.page==='dashboard'){$('#view-content').insertAdjacentHTML('afterbegin',`<div class="demo-callout" style="margin:0 0 20px">${icon('sun')}Chào ${esc(state.user?.name||(state.auth?'bạn':'bạn học mới'))}! Hôm nay là một ngày tốt để tiến thêm một bước trên hành trình học tập.</div>`);icons();}}else if(state.page==='courses')await catalog();else if(state.page==='careers')careerCatalog();else if(state.page==='saved')await savedView();else if(state.page==='profile')await profileView();else if(state.page==='graph'){$('#view-content').innerHTML=graphView();icons();await drawGraph();}else if(state.page==='admin')await adminView();else{$('#view-content').innerHTML=welcome();icons();}}
function guide(){openModal('Học đúng hướng, từng bước một','Một vài điều để bạn bắt đầu hành trình học tập.',`<div class="guide-steps">${[['1','Chọn mục tiêu của bạn','Nhấn “Tạo lộ trình mới”, chọn ngành, khóa tuyển sinh và nghề nghiệp mong muốn.'],['2','Khám phá 10 học phần phù hợp','Hệ thống xét toàn bộ tổ hợp 10/15 và tối ưu kỹ năng nghề nghiệp; thứ tự học tôn trọng môn tiên quyết.'],['3','Hiểu vì sao môn học được chọn','Mở chi tiết để xem thành phần điểm và đường đi giải thích trên đồ thị tri thức.'],['4','Lưu hành trình, cập nhật tiến độ','Đăng ký hoặc đăng nhập để lưu nhiều lộ trình. Đánh dấu môn đã hoàn thành để cập nhật hành trình.'],['5','So sánh và mang theo lộ trình','So sánh hai nghề nghiệp hoặc xuất PDF từ màn hình lộ trình đã tạo.']].map(([n,title,p])=>`<div class="guide-step"><span>${n}</span><div><h3>${title}</h3><p>${p}</p></div></div>`).join('')}</div><div class="demo-callout">${icon('info')}Bản demo hiển thị dữ liệu minh họa, không thay thế chương trình đào tạo hay tư vấn đăng ký học phần chính thức của NEU.</div>`,`<button class="btn btn-white" data-action="export">${icon('download')}Xuất PDF lộ trình</button><button class="btn btn-primary" data-action="close">Bắt đầu khám phá ${icon('arrow-right')}</button>`);}
document.addEventListener('click',async event=>{const btn=event.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action,id=btn.dataset.id;try{
 if(action==='close')closeModal();else if(action==='create')createModal();else if(action==='select-career')createModal(id);else if(action==='guide')guide();else if(action==='search'){window.location.href='/courses';}else if(action==='notifications')openModal('Thông báo học tập','Hành trình của bạn luôn được cập nhật.',`<div class="guide-step"><span>${icon('sparkles')}</span><div><h3>Sẵn sàng cho bước đầu tiên</h3><p>Tạo lộ trình, chọn mục tiêu nghề nghiệp và bắt đầu với những học phần nền tảng. Tiến độ của bạn được lưu sau khi đăng nhập.</p></div></div>`,`<button class="btn btn-primary" data-action="close">Đã hiểu</button>`);
 else if(action==='account'){if(!state.auth)authModal();else openModal('Tài khoản của bạn','Quản lý hồ sơ và phiên đăng nhập.',`<a class="btn btn-white" href="/profile">${icon('user-round')}Mở hồ sơ học tập</a><button class="btn btn-danger" style="margin-left:10px" data-action="logout">${icon('log-out')}Đăng xuất</button>`);}else if(action==='demo-fill'){const account=(await demoAccountsPromise).find(a=>a.key===id);if(account&&$('#auth-form')){$('#auth-email').value=account.email;$('#auth-password').value=account.password;$('#auth-form button[type=submit]').focus();}}else if(action==='login')authModal();else if(action==='register')authModal(true);else if(action==='logout'){await api('/auth/logout',{method:'POST',body:'{}'});localStorage.removeItem('neu-run');window.location.href='/';}
 else if(action==='detail')await showDetail(id);else if(action==='tab'){state.tab=id;renderRoadmap();}else if(action==='save')await saveModal();else if(action==='export'){if(!state.run)throw new Error('Hãy tạo lộ trình trước khi xuất PDF.');const link=document.createElement('a');link.href='/api/recommendations/'+state.run.run_id+'/pdf';link.download='lo-trinh-hoc-tap.pdf';document.body.append(link);link.click();link.remove();toast('Đã chuẩn bị bản PDF tiếng Việt cho bạn.');}
 else if(action==='progress'){if(!requireAuth('detail:'+id))return;btn.disabled=true;await api('/progress/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({status:btn.dataset.status})});state.progress[id]=btn.dataset.status;const inputs=JSON.parse(localStorage.getItem('neu-inputs')||'{}');delete inputs.completed;await generate(inputs);await renderPage();await showDetail(id);toast('Đã cập nhật tiến độ học tập.');}
 else if(action==='show-path'){closeModal();if(state.page!=='roadmap'&&state.page!=='graph'){sessionStorage.setItem('neu-graph-course',id);window.location.href='/graph';return;}state.tab='graph';if(state.page==='roadmap'){ $('#view-content').innerHTML=hero()+stats()+tabs()+graphView();icons();}await drawGraph(id);}
 else if(action==='graph-fit')state.graph?.fit(undefined,40);else if(action==='graph-reset')resetGraph();else if(action==='graph-select'){const node=state.graph?.getElementById(id);selectGraphNode(node);}else if(action==='graph-zoom-in'||action==='graph-zoom-out'){if(state.graph)state.graph.zoom({level:Math.max(state.graph.minZoom(),Math.min(state.graph.maxZoom(),state.graph.zoom()*(action==='graph-zoom-in'?1.25:.8))),renderedPosition:{x:state.graph.width()/2,y:state.graph.height()/2}});}else if(action==='compare')await compareModal();else if(action==='run-compare'){btn.disabled=true;try{await runComparison();}finally{btn.disabled=false;}}
 else if(action==='load-saved'){localStorage.setItem('neu-run',id);sessionStorage.setItem('neu-load-saved','true');window.location.href='/';}else if(action==='rename')openModal('Đổi tên lộ trình','Giữ lại một cái tên có ý nghĩa với bạn.',`<form id="rename-form" data-id="${id}"><div class="field"><label>Tên mới</label><input name="name" value="${esc(btn.dataset.name)}" required maxlength="150"></div><div class="form-error"></div></form>`,`<button class="btn btn-white" data-action="close">Hủy</button><button class="btn btn-primary" type="submit" form="rename-form">Lưu tên mới</button>`);
 else if(action==='delete-saved')confirmDelete('Xóa lộ trình đã lưu?','Lộ trình này sẽ được xóa khỏi danh sách của bạn. Tiến độ học phần vẫn được giữ lại.','delete-saved-confirm',id);else if(action==='delete-saved-confirm'){await api('/roadmaps/'+id,{method:'DELETE'});closeModal();await savedView();toast('Đã xóa lộ trình.');}
 else if(action==='admin-kind')await adminView(id);else if(action==='admin-edit')adminEditor(Number(id));else if(action==='admin-add')adminEditor(null);else if(action==='admin-delete')confirmDelete('Xóa bản ghi?','Bản ghi đang được tham chiếu có thể cần gỡ liên kết trước khi xóa.','admin-delete-confirm',id);else if(action==='admin-delete-confirm'){await api('/admin/'+state.adminKind+'/'+encodeURIComponent(id),{method:'DELETE'});closeModal();await adminView();toast('Đã xóa bản ghi.');}
 }catch(error){if($('#modal').open)inlineError(error.message);else toast(error.message,true);} });
function confirmDelete(title,text,action,id){openModal(title,'',`<p style="font-size:11px;color:#8b9fad">${esc(text)}</p>`,`<button class="btn btn-white" data-action="close">Giữ lại</button><button class="btn btn-danger" data-action="${action}" data-id="${esc(id)}">${icon('trash-2')}Xác nhận xóa</button>`);}
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;const data=Object.fromEntries(new FormData(form));const submit=$(`[form="${form.id}"]`)||$('button[type="submit"]',form);if(submit)submit.disabled=true;try{
 if(form.id==='create-form'){const curriculum=state.curricula.find(c=>c.major_id===data.major_id&&c.cohort===data.cohort&&c.source===data.source);if(!curriculum)throw new Error('Chưa đồng bộ chương trình và khóa này từ nguồn đã chọn. Quản trị viên có thể đồng bộ trong trang quản trị.');await generate({curriculum_id:curriculum.id,career_id:data.career_id,current_semester:Number(data.current_semester),interests:data.interests?[data.interests]:[]});closeModal();if(state.page==='roadmap'||state.page==='dashboard'){state.tab='timeline';renderRoadmap();toast('Lộ trình của bạn đã sẵn sàng!');}else window.location.href='/';}
 else if(form.id==='auth-form'){const user=await api('/auth/'+(form.dataset.register==='true'?'register':'login'),{method:'POST',body:JSON.stringify(data)});await finishAuthentication(user);}
 else if(form.id==='save-form'){await api('/roadmaps',{method:'POST',body:JSON.stringify({...data,run_id:state.run.run_id})});closeModal();toast('Đã lưu lộ trình vào tài khoản của bạn.');}
 else if(form.id==='rename-form'){await api('/roadmaps/'+form.dataset.id,{method:'PATCH',body:JSON.stringify(data)});closeModal();await savedView();toast('Đã đổi tên lộ trình.');}
 else if(form.id==='profile-form'||form.id==='password-form'){await api('/profile',{method:'PATCH',body:JSON.stringify(data)});toast(form.id==='profile-form'?'Đã lưu thông tin cá nhân.':'Đã đổi mật khẩu.');if(form.id==='password-form')form.reset();}
 else if(form.id==='weights-form'){const weights=Object.fromEntries(Object.entries(data).map(([k,v])=>[k,Number(v)]));await api('/admin/weights',{method:'PATCH',body:JSON.stringify(weights)});toast('Đã lưu cấu hình trọng số.');}
 else if(form.id==='sync-form'){toast('Đang kết nối nguồn dữ liệu NEU...');const result=await api('/admin/sync',{method:'POST',body:JSON.stringify(data)});await adminView('sync');toast('Đã đồng bộ '+result.records+' bản ghi từ API NEU.');}
 else if(form.id==='admin-editor-form'){let record;try{record=JSON.parse(data.json);}catch{throw new Error('JSON chưa hợp lệ. Hãy kiểm tra dấu ngoặc và dấu phẩy.');}const id=form.dataset.id;await api('/admin/'+form.dataset.kind+(id?'/'+encodeURIComponent(id):''),{method:id?'PATCH':'POST',body:JSON.stringify(record)});closeModal();await adminView();toast('Đã lưu bản ghi.');}
 }catch(error){if($('#modal').open)inlineError(error.message);else toast(error.message,true);}finally{if(submit&&submit.isConnected)submit.disabled=false;}});
document.addEventListener('change',event=>{if(event.target.id==='group-select'){state.group=event.target.value;renderRoadmap();}else if(event.target.id==='catalog-source')catalog(event.target.value).catch(e=>toast(e.message,true));});
document.addEventListener('input',event=>{const input=event.target;if(input.id==='course-search'){const text=input.value.toLocaleLowerCase('vi').trim();const courses=state.catalog.filter(c=>(c.name+' '+c.code).toLocaleLowerCase('vi').includes(text));$('#catalog-grid').innerHTML=courses.length?courses.map(c=>courseCard(state.run?.items.find(x=>x.id===c.id)||c)).join(''):empty('Chưa tìm thấy môn học','Thử một tên môn hoặc mã học phần khác.','search');$('#catalog-count').textContent=courses.length+' học phần';icons();}else if(input.id==='career-search'){filterCareerCards();}else if(input.id==='graph-search'){searchGraph(input.value);}});
$('#menu-toggle').addEventListener('click',()=>{$('#sidebar').classList.toggle('open');$('#mobile-overlay').classList.toggle('visible');});$('#mobile-overlay').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#mobile-overlay').classList.remove('visible');});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(state.page==='courses')$('#course-search')?.focus();else location.href='/courses';}});
async function init(){const title=titles[state.page]||titles.roadmap;$('#page-title').innerHTML=esc(title[0])+'<span class="heading-dot">.</span>';$('#page-subtitle').textContent=title[1];$('#breadcrumb-title').textContent=title[0];document.title=title[0]+' · NEU Learning Path';icons();try{const [majors,curricula,careers]=await Promise.all([api('/majors'),api('/curricula'),api('/careers')]);Object.assign(state,{majors,curricula,careers});if(state.auth){const [progress,profile]=await Promise.all([api('/progress'),api('/profile')]);state.progress=Object.fromEntries(progress.map(p=>[p.course_id,p.status]));state.user=profile;}const saved=localStorage.getItem('neu-run');if(saved){try{state.run=await api('/recommendations/'+saved);}catch{localStorage.removeItem('neu-run');}}if(!state.run)await defaultRun();if(sessionStorage.getItem('neu-load-saved')){const c=state.curricula.find(c=>c.id===state.run.curriculum_id);localStorage.setItem('neu-inputs',JSON.stringify({curriculum_id:c?.id||state.run.curriculum_id,career_id:state.run.career_id,current_semester:3}));sessionStorage.removeItem('neu-load-saved');}await renderPage();if(state.page==='graph'){const course=sessionStorage.getItem('neu-graph-course');if(course){highlightCourse(course);sessionStorage.removeItem('neu-graph-course');}}}catch(error){$('#view-content').innerHTML=empty('Chưa thể tải dữ liệu',error.message,'cloud-alert',`<button class="btn btn-primary" onclick="location.reload()">Thử lại</button>`);icons();}}
document.addEventListener('change',event=>{
 if(event.target.id==='source-input'){
  const callout=$('#create-form .demo-callout');
  callout.innerHTML=icon('info')+'<span>'+ (event.target.value==='NEU'?'Chương trình NEU dùng dữ liệu chính thức đã đồng bộ. Hệ thống sẽ từ chối tạo lộ trình khi chưa xác minh nhóm tự chọn, số môn cần chọn và liên kết kỹ năng có bằng chứng.':'Dữ liệu minh họa – không phải chương trình đào tạo chính thức. Quy tắc 10/15 đang áp dụng cho bộ dữ liệu demo.')+'</span>';icons();
 }
});
document.addEventListener('click',event=>{
 const button=event.target.closest('[data-action]');if(!button)return;
 const action=button.dataset.action;
 if(action==='career-filter'){state.careerGroup=button.dataset.id;filterCareerCards();}
 else if(action==='career-clear'){$('#career-search').value='';filterCareerCards();$('#career-search').focus();}
 else if(action==='career-reset'){state.careerGroup='all';$('#career-search').value='';filterCareerCards();}
 else if(action==='career-detail')careerDetails(button.dataset.id);
});
init();
